function validUsername(name) {
  return /^[a-zA-Z0-9_]{3,16}$/.test(name);
}
const names = ['rolake_19', 'a!', 'toolongusername12345'];
for (const n of names) console.log(n + ': ' + (validUsername(n) ? 'valid' : 'rejected'));

