function scanInput(input) {
  const t = input.toLowerCase();
  const bad = ['<script', 'javascript:', 'onerror=', 'drop table'];
  for (const b of bad) if (t.includes(b)) return 'FLAGGED';
  return 'SAFE';
}
const inputs = ['hello world', '<ScRiPt>alert(1)</script>', 'nice profile pic'];
for (const i of inputs) console.log(scanInput(i) + ': ' + i);

